-- =====================================================================
-- TrendsTees | Migration 004 | Countries, states, cities (checkout dropdowns)
-- =====================================================================
-- countries: saare 250 countries. Sirf US ka is_shipping_enabled = true.
--            Future mein koi country kholni ho to us ka flag true karo
--            aur us ki states/cities load karo.
-- states   : US ki 50 states + DC
-- cities   : US ki cities (state ke hisaab se)
-- Data source: dr5hn/countries-states-cities-database (ODbL license)
-- =====================================================================


CREATE TABLE public.countries (
  country_code        char(2)      PRIMARY KEY,
  country_name        varchar(100) NOT NULL,
  phone_code          varchar(20),
  is_shipping_enabled boolean      NOT NULL DEFAULT false,
  display_order       smallint     NOT NULL DEFAULT 100
);

CREATE TABLE public.states (
  state_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  country_code  char(2)      NOT NULL REFERENCES public.countries(country_code),
  state_code    varchar(10)  NOT NULL,
  state_name    varchar(100) NOT NULL,
  is_active     boolean      NOT NULL DEFAULT true,
  CONSTRAINT uq_states_country_code UNIQUE (country_code, state_code)
);

CREATE TABLE public.cities (
  city_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  state_id   bigint       NOT NULL REFERENCES public.states(state_id),
  city_name  varchar(120) NOT NULL,
  is_active  boolean      NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX uq_cities_state_name ON public.cities (state_id, lower(city_name));
CREATE INDEX ix_states_country ON public.states (country_code, state_name);

