INSERT INTO public.cities (state_id, city_name)
SELECT s.state_id, t.city_name
FROM tmp_cities t JOIN public.states s ON s.country_code = 'US' AND s.state_code = t.state_code;


-- Check
SELECT (SELECT count(*) FROM countries) AS countries,
       (SELECT count(*) FROM countries WHERE is_shipping_enabled) AS shipping_countries,
       (SELECT count(*) FROM states) AS states,
       (SELECT count(*) FROM cities) AS cities;
